<?php require_once __DIR__.'/includes/bootstrap.php';require_role('customer');$services=db()->query('SELECT s.*,b.business_name,b.location FROM services s JOIN businesses b ON b.id=s.business_id WHERE s.is_active=1')->fetchAll();$q=db()->prepare('SELECT t.*,b.business_name,s.service_name FROM queue_tickets t JOIN businesses b ON b.id=t.business_id JOIN services s ON s.id=t.service_id WHERE t.customer_user_id=? ORDER BY t.id DESC LIMIT 10');$q->execute([$_SESSION['user_id']]);$mine=$q->fetchAll();$title='Customer dashboard';require 'includes/header.php';?><h1>Find a service</h1><section class="grid"><?php foreach($services as $s):?><article class="panel"><h3><?=e($s['business_name'])?></h3><p><?=e($s['service_name'])?> · <?=e($s['location'])?></p><form method="post" action="join_queue.php"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="service_id" value="<?=$s['id']?>"><button>Join queue</button></form></article><?php endforeach;?></section><section class="panel"><h2>Your tickets</h2><?php foreach($mine as $t):?><p><b><?=e($t['ticket_code'])?></b> — <?=e($t['business_name'])?> — <?=e($t['status'])?> — <a href="ticket.php?id=<?=$t['id']?>">View ticket</a></p><?php endforeach;?></section><?php require 'includes/footer.php';?>